set identity_insert [security].[Role] on;
insert into [security].[Role] (ID, Uid, Name, Description, [Permissions], CreatedBy, CreatedOn, UpdatedBy, UpdatedOn)
	select	ID, Uid, Name, Description, 1, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn
	from	ResponsibilityType
set identity_insert [security].[Role] off;
